    gableP(rf, -47.5, -40.5, ZN - 0.4, ZS + 0.4, YD + 8.0, YD + 12.5, 1);
    // three-storey flat-roofed section and the inshore annex: windows, cornice, the annex gable with its pediment and the carriage arch
