    for (let x = -38; x <= 30; x += 12) for (const z of [-13.9, 3.2]){ segP(B.p(TR), [x, YD, z], [x, YD + 3.6, z], 0.07, 4); LSph(g, 0.22, x, YD + 3.8, z, {c:'#fff0cc', glow:'#ffe2a8', gk:1.4}, 1, 6); }
