      GL = {c:'#7f969c', m:1, fh:3.2, cw:2.0}, CU = {c:'#6f9e8a'}, RF = {c:'#77786f'}, WD = {c:'#5e4a38'}, DKs = {c:'#1f2326', glow:'#ffcf8a', gk:0.25};
    const gn = B.p(GN), gn2 = B.p(GN2), cr = B.p(CR), wn = B.p(WN), rf = B.p(RF);
    const G = -0.9, Y0 = -6, H = y => G + y, YC = H(15);
