    for (let k = 0; k < nb; k++){ const s = (k + 0.5)*LN/nb; if (Math.abs(s - mN) < 15.5){ continue; }
      rectE(wn, eN, s - 2.0, s + 2.0, G + 0.4, G + 5.4, 0.05); rectE(wn, eN, s - 1.6, s + 1.6, H(7.4), H(12.8), 0.05); rectE(B.p(BL), eN, s - 1.6, s + 1.6, H(13.1), H(13.9), 0.06); }
    // loggia: recess with a cream vault, four giant columns between two piers, the entrance below
