    { const R = offP(PT[3][2], 1.0); prismP(cr, R, YC, H(18.2)); winsP(wn, R, H(15.6), H(17.8), 3.0, 2.6, 1.6, 1.9, 0.05);
      const Rg = offP(PT[3][2], 2.6); prismP(B.p(GL), Rg, H(18.2), H(21.6)); mullP(gn2, Rg, H(18.2), H(21.6), 2.2, 0.15, 0.05); wallsP(gn2, offP(Rg, -0.25), H(21.3), H(21.9)); }
    { const R = offP(PT[2][2], 1.0); prismP(B.p(GL), R, YC, H(20)); mullP(gn2, R, YC, H(20), 2.2, 0.15, 0.05); }
