place('nyfraunces');


// ===== Museum of Jewish Heritage - A Living Memorial to the Holocaust (Kevin Roche John Dinkeloo, 1997; Robert M. Morgenthau
// Wing 2003), Battery Park City. The six-sided core building in grey granite with its six-tiered stepped hexagonal roof (the
// real OSM tiers, a small glazed lantern at the apex), few narrow windows, the recessed glass entrance towards Battery Place;
// the long granite-and-glass Morgenthau Wing with its window bands, and on its roof terrace the memorial garden of eighteen
// hollowed boulders, each with a young tree growing from the stone. Accurate, quiet architecture only; no text or symbols.
// Frame: +x east (Battery Place), -x the river.
LANDMARKS.nyjewishheritage = {zh:'犹太遗产博物馆', en:'Museum of Jewish Heritage', cat:'new', r:52, h:26,
  lt:{m:0, c:'#f4ead8', k:0.65, e:0.7},
  build(){
    const g = new THREE.Group(), B = mkB(), HX = FD.nyjewishheritage[0], WG = FD.nyjewishheritage[1];
    const GS = {c:'#b4b0a8'}, GS2 = {c:'#9e9a93'}, DK = {c:'#2c3034', glow:'#ffe2b4', gk:0.45}, GL = {c:'#5d6a70', m:1, fh:4.4, cw:1.8}, RK = {c:'#8a8379'}, TRc = {c:'#5f7a45'}, TK = {c:'#5a4a3a'}, LG = {c:'#c6d2d4', glow:'#fff1d0', gk:0.8};
    const gs = B.p(GS), gs2 = B.p(GS2), dk = B.p(DK);
    const G = -4.4, Y0 = -9.5, H = y => G + y;
    // ---- hexagonal core building: walls, narrow vertical windows, the six tiers
    const P = HX.ring;
    prismP(gs, P, Y0, H(13.0));
    stripsP(dk, P, H(3.0), H(11.5), 6.5, 0.45, 0.05);
    bandsP(gs2, P, H(0), H(12.5), 13.0, 0.35, 0.04);
    const tiers = HX.parts.filter(q => q[0] >= 12.9).sort((a, b) => a[0] - b[0]);
    for (const [b0, t0, R] of tiers){ prismP(gs2, R, H(b0), H(t0)); wallsP(dk, offP(R, -0.05), H(b0) + 0.15, H(b0) + 0.55); }
    { const R = tiers[tiers.length - 1][2]; let cx = 0, cz = 0; for (const p of R){ cx += p[0]/6; cz += p[1]/6; }
      const L6 = R.map(p => [cx + (p[0] - cx)*0.5, cz + (p[1] - cz)*0.5]); prismP(gs2, L6, H(24), H(25.2)); const L7 = R.map(p => [cx + (p[0] - cx)*0.28, cz + (p[1] - cz)*0.28]); prismP(B.p(LG), L7, H(25.2), H(26.0)); }
    // entrance: the hexagon face turned most to the east, recessed glass with a thin canopy
    { let bi = 0, bx = -1; for (let i = 0; i < 6; i++){ const n = outN(P, i); if (n[0] > bx){ bx = n[0]; bi = i; } }
      const e = edgeF(P, bi); rectE(B.p(GL), e, e.L/2 - 3.5, e.L/2 + 3.5, H(0), H(4.6), 0.05); boxE(gs2, e, e.L/2, 1.2, H(4.6), 9.0, 0.35, 2.6); }
    // ---- Morgenthau Wing: granite volume, window bands, glazed river end, roof terrace with the garden of stones
    const W = WG.ring;
    prismP(gs, W, Y0, H(25.5));
    for (const y of [4.6, 10.1, 15.6, 21.1]) bandsP(B.p(GL), W, H(y - 2.6) - 100, H(y), 100, 2.6, 0.05);
    { const A = offP(W, 0.45); wallsP(gs2, offP(W, -0.05), H(25.5), H(26.6)); }
    // memorial garden (~390 m2) on the roof terrace at the wing's east end: 18 boulders forming narrow paths, a dwarf oak sapling growing from each
    { const pts = []; const bb = bbP(W); let tries = 0, rng = LMCTX.rng;
      while (pts.length < 18 && tries++ < 20000){ const x = bb[0] + rng()*(bb[2] - bb[0]), z = bb[1] + rng()*(bb[3] - bb[1]);
        if (Math.hypot(x - 10, z - 5) > 11.5 || !inPoly(W, x, z) || dPoly(W, x, z) < 2.4) continue; if (pts.some(p => Math.hypot(p[0] - x, p[1] - z) < 3.7)) continue; pts.push([x, z]); }
      for (const [x, z] of pts){ const y = H(25.5), s = 0.8 + 0.35*rng();
        latheP(B.p(RK), [[0.95*s, y], [1.2*s, y + 0.5*s], [1.1*s, y + 1.05*s], [0.55*s, y + 1.35*s], [0.3*s, y + 1.3*s]], x, z, 7, x);
        treeP(B, x, y + 1.0*s, z, 0.36, TRc, TK, x); } }
    B.flush(g);
    return g; }};
place('nyjewishheritage');

